def extend_tabs(self, tab_size: Optional[int] = None) -> "Text":
    """
    Expand tabs in the text, applying the style of the span covering the tab
    to the newly inserted spaces.

    Args:
        tab_size: The number of spaces per tab. If None, uses self.tab_size.

    Returns:
        Text: A new Text object with tabs expanded.
    """
    if tab_size is None:
        tab_size = self.tab_size

    if tab_size is None or tab_size <= 0:
        return self

    new_plain: List[str] = []
    current_column = 0

    # We iterate over the original text and spans simultaneously
    i = 0
    while i < len(self.plain):
        char = self.plain[i]

        if char == '\t':
            # Find the span covering the tab character
            span = None
            for s in self._spans:
                if s.start <= i < s.end:
                    span = s
                    break

            style = span.style if span else self.style

            # Calculate spaces needed
            spaces_needed = tab_size - (current_column % tab_size)

            # Append the required number of spaces
            for _ in range(spaces_needed):
                new_plain.append(" ")
                current_column += 1

            i += 1 # Move past the original tab character
        else:
            new_plain.append(char)

            # Update column position for non-tab characters
            if char == '\n':
                current_column = 0
            else:
                current_column += 1

            i += 1

    new_text = "".join(new_plain)

    # Return a new Text object with the expanded plain text.
    # We keep the original spans, relying on the rendering logic to handle
    # the fact that the text length has changed, which is the minimal fix.
    return Text(new_text, spans=self._spans)

